when HTTP_REQUEST {
    if { [HTTP::path] starts_with "/protected_uri" } {
        ECA::enable
        ECA::select select_ntlm:/Common/exch_ntlm_auth_config
    } else {
        ECA::disable
    }
    log local0. "User [ECA::username]@[ECA::domainname], Client Machine [ECA::client_machine_name], Auth Status [ECA::status]"
}
